12:     final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
13:     final MockNewsRepository mockNewsRepository = MockNewsRepository();
14:     final MockSettingsRepository mockSettingsRepository = MockSettingsRepository();
15: 
16:     final ImageProvider homeImage = Image.asset('assets/icons/home.png').image;
