31: 
32:       when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => const CurrencyPage(items: [], page: 0, hasMore: false));
33:       when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => []);
