import 'package:flutter/material.dart';

class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;
  int _refreshCounter = 0;

  void _onRefreshAll() async {
    final BuildContext ctx = context;
    setState(() {
      _refreshCounter++;
    });
    if (!ctx.mounted) return;
    ScaffoldMessenger.of(ctx).showSnackBar(
      SnackBar(
        content: Text(ctx.loc.refreshAll),
        duration: const Duration(milliseconds: 800),
      ),
    );
  }

  static const List<Widget> _pages = <Widget>[
    CurrencyListPage(),
    NewsListPage(),
    ProfilePage(),
  ];

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  @override
  Widget build(BuildContext context) {
    final Widget currentPage = _pages[_selectedIndex];
    final AppLocalizations loc = context.loc;
    final int refreshKey = _refreshCounter;

    return Scaffold(
      appBar: AppBar(
        title: Text(loc.currencyRate),
        actions: <Widget>[
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: loc.refreshAll,
            onPressed: _onRefreshAll,
          ),
        ],
      ),
      body: ValueListenableBuilder<int>(
        valueListenable: ValueNotifier(refreshKey) ..value = refreshKey,
        builder: (BuildContext context, int _, Widget? child) {
          return IndexedStack(
            index: _selectedIndex,
            children: <Widget>[
              CurrencyListPage(key: Key('currency_$refreshKey')),
              NewsListPage(key: Key('news_$refreshKey')),
              const ProfilePage(),
            ],
          );
        },
      ),
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          boxShadow: <BoxShadow>[
            BoxShadow(
              color: context.colors.bottomNavBarShadow,
              blurRadius: 25,
              offset: const Offset(0.0, 0.75),
            ),
          ],
        ),
        child: BottomNavigationBar(
          currentIndex: _selectedIndex,
          onTap: _onItemTapped,
          items: [
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/home.png',
                isSelected: _selectedIndex == 0,
              ),
              label: loc.currencyRate,
            ),
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/news.png',
                isSelected: _selectedIndex == 1,
              ),
              label: loc.news,
            ),
            BottomNavigationBarItem(
              icon: const Icon(Icons.person),
              label: loc.profile,
            ),
          ],
        ),
      ),
    );
  }
}

class TabWidget extends StatelessWidget {
  const TabWidget({
    super.key,
    required this.assetPath,
    required this.isSelected,
  });

  final String assetPath;
  final bool isSelected;

  @override
  Widget build(BuildContext context) {
    final ThemeColors colors = context.colors;

    return SizedBox.square(
      dimension: 24,
      child: Image.asset(
        assetPath,
        color: isSelected ? colors.bottomNavBarSelectedItem : colors.bottomNavBarUnselectedItem,
      ),
    );
  }
}
